#pragma once
#include <cstddef>
#include <istream>
#include <ostream>

namespace ws {
    class Buffer;

    namespace io {
        class IReader {
        public:
            virtual ~IReader() noexcept = default;
            virtual std::size_t ReadFrom(Buffer& buf) = 0;
        };

        class IWriter {
        public:
            virtual ~IWriter() noexcept = default;
            virtual std::size_t WriteTo(Buffer& buf) = 0;
        };

        class IReadWriter : public virtual IReader, public virtual IWriter {};

        class Null : public virtual IReadWriter {
        public:
            std::size_t WriteTo(Buffer& buf) noexcept override;
            std::size_t ReadFrom(Buffer& buf) noexcept override;
        };

        class StringStream : public virtual IReadWriter {
        public:
            explicit StringStream(std::istream& read, std::ostream& write) noexcept;
            ~StringStream() = default;
            StringStream(const StringStream&) = delete;
            StringStream& operator=(const StringStream&) = delete;

            std::size_t WriteTo(Buffer& buf) noexcept override;
            std::size_t ReadFrom(Buffer& buf) noexcept override;

        private:
            std::istream& read_;
            std::ostream& write_;
        };

        class FileDescriptor : public virtual IReadWriter {
        public:
            explicit FileDescriptor(int read, int write) noexcept;
            ~FileDescriptor() = default;
            FileDescriptor(const FileDescriptor&) = delete;
            FileDescriptor& operator=(const FileDescriptor&) = delete;

            std::size_t WriteTo(Buffer& buf) override;
            std::size_t ReadFrom(Buffer& buf) override;

        private:
            int read_;
            int write_;
        };
    }
}

#include "io.h"
#include <util.h>

namespace ws {
    namespace io {
        std::size_t Null::WriteTo(Buffer& buf) noexcept {
            const auto n = buf.writable_bytes();
            buf.append(nullptr, n);
            return n;
        }

        std::size_t Null::ReadFrom(Buffer& buf) noexcept {
            const auto n = buf.readable_bytes();
            buf.retrieve(n);
            return n;
        }

        StringStream::StringStream(std::istream& read, std::ostream& write) noexcept : read_(read), write_(write) {}

        std::size_t StringStream::WriteTo(Buffer& buf) noexcept {
            const auto n = buf.writable_bytes();
            if (n == 0) return 0;
            char* p = buf.begin_write();
            read_.read(p, static_cast<std::streamsize>(n));
            const std::size_t m = static_cast<std::size_t>(read_.gcount());
            buf.has_written(m);
            return m;
        }

        std::size_t StringStream::ReadFrom(Buffer& buf) noexcept {
            const auto n = buf.readable_bytes();
            if (n == 0) return 0;
            write_.write(buf.data(), static_cast<std::streamsize>(n));
            buf.retrieve(n);
            return n;
        }

        FileDescriptor::FileDescriptor(int read, int write) noexcept : read_(read), write_(write) {}

        std::size_t FileDescriptor::WriteTo(Buffer& buf) {
            const auto n = buf.writable_bytes();
            if (n == 0) return 0;
            char* p = buf.begin_write();
            ssize_t m = ::read(read_, p, static_cast<size_t>(n));
            if (m < 0) {
                ThrowLastSystemError("FileDescriptor::WriteTo read failed");
            }
            buf.has_written(static_cast<std::size_t>(m));
            return static_cast<std::size_t>(m);
        }

        std::size_t FileDescriptor::ReadFrom(Buffer& buf) {
            const auto n = buf.readable_bytes();
            if (n == 0) return 0;
            ssize_t m = ::write(write_, buf.data(), static_cast<size_t>(n));
            if (m < 0) {
                ThrowLastSystemError("FileDescriptor::ReadFrom write failed");
            }
            buf.retrieve(static_cast<std::size_t>(m));
            return static_cast<std::size_t>(m);
        }
    }
}
